export const FAWAID_ITEMS = [
  { text: "بدر أول معركة فاصلة؛ وفيها نصر الله المؤمنين، وبرهنت على أن النصر من عند الله لا من كثرة العدد والعدة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "السيرة", source: "صحيح البخاري — كتاب المغازي", author_name: "الإمام البخاري" },
  { text: "إن مع العسر يسراً — تكررت في سورة الشرح إشارة إلى أن العسر واحد واليسر اثنان؛ فلا ييأس المؤمن من رحمة الله. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "التفسير", source: "الشرح: 5-6 — تفسير ابن كثير", author_name: "ابن كثير" },
  { text: "الاستعاذة قبل التلاوة سنة؛ لأن الشيطان يحاول صرف القارئ عن الخشوع، فالاستعاذة تحصنه من وسوسة الشيطان. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "التفسير", source: "«فإذا قرأت القرآن فاستعذ بالله من الشيطان الرجيم» — النحل: 98", author_name: "القرآن الكريم" },
  { text: "لا ضرر ولا ضرار — قاعدة فقهية جامعة في رفع المفسدة وحفظ المصالح، وهي من أصول الفقه التي يُبنى عليها التشريع الشرعي. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الفقه", source: "ابن ماجه ٢٣٤١ — حسّنه الألباني بمجموع الطرق", author_name: "سنن ابن ماجه" },
  { text: "المشقة تجلب التيسير — من أهم القواعد الفقهية الكبرى؛ فالشرع يرحم العباد ولا يكلفهم ما لا يطيقون في الدنيا والآخرة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الفقه", source: "الأشباه والنظائر — ابن نجيم", author_name: "ابن نجيم" },
  { text: "مروا أولادكم بالصلاة لسبع، ثم اضربوهم عليها لعشر؛ وهذا من أصول تربية الأولاد على العبادة مبكراً. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "التربية", source: "رواه أبو داود — حسنه الألباني", author_name: "سنن أبي داود" },
  { text: "المرء على دين خليله فلينظر أحدكم من يخالل؛ فالصحبة الصالحة سبب للصلاح والصحبة السيئة سبب للضرر في الدنيا والآخرة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "التربية", source: "رواه أبو داود — حسنه الألباني", author_name: "سنن أبي داود" },
  { text: "من تواضع لله رفعه؛ فالرفعة ثمرة الخفض لله، وهذا من آداب الإسلام التي تُقرب العبد من ربه تعالى في الدنيا والآخرة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الآداب", source: "رواه مسلم", author_name: "صحيح مسلم" },
  { text: "إن الله يحب إذا عمل أحدكم عملاً أن يتقنه؛ فالإتقان من مكارم الأخلاق التي أمر بها الشرع في كل عمل في الدنيا والآخرة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الأخلاق", source: "رواه البيهقي — صحيح الألباني", author_name: "شعب الإيمان" },
  { text: "كلمتان خفيفتان على اللسان ثقيلتان في الميزان حبيبتان إلى الرحمن: سبحان الله وبحمده، سبحان الله العظيم. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الحديث", source: "متفق عليه", author_name: "صحيح البخاري" },
  { text: "من قرأ آية الكرسي دبر كل صلاة لم يمنعه من دخول الجنة إلا أن يموت؛ فالتعامل مع كتاب الله يستوجب تدبره وحفظه والعمل بما فيه. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "القرآن", source: "رواه النسائي — صححه الألباني في السلسلة الصحيحة (972)", author_name: "سنن النسائي" },
  { text: "من أتقن العربية فتح له باب الفهم على الكتاب والسنة؛ ولغة القرآن ليست وسيلة فحسب بل هي من شريعته في الدنيا والآخرة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "اللغة", source: "اقتضاء الصراط المستقيم — ابن تيمية", author_name: "ابن تيمية" },
  { text: "من حسن إسلام المرء تركه ما لا يعنيه؛ فترك ما لا يعنيه من أعظم موفّرات الوقت والطاقة والعلاقات، وهذا من آداب الإسلام التي تُجمّل المسلم وتُقربه من ربه.", category: "الآداب", source: "رواه الترمذي (2317) — حسنه الألباني", author_name: "سنن الترمذي" },
  { text: "الدنيا سجن المؤمن وجنة الكافر؛ فمن عرف قدر الآخرة قلّ اهتمامه بالدنيا وزاد عمله لما بعد الموت، وهذا من أصول الاعتقاد التي يُبنى عليها إيمان المسلم وعمله.", category: "العقيدة", source: "رواه مسلم (2956)", author_name: "صحيح مسلم" },
  { text: "من كان يؤمن بالله واليوم الآخر فليحسن إلى جاره؛ فحسن الجوار من أعظم أسباب تمام الإيمان وصلاح المجتمع، وهذا من آداب الإسلام التي تُجمّل المسلم وتُقربه من ربه.", category: "الآداب", source: "متفق عليه", author_name: "صحيح البخاري" },
  { text: "إن الله يحب التواضع ويكره الكبر؛ فالتواضع يرفع صاحبه والكبر يحطّه، وهذا من مكارم الأخلاق التي أمر بها الشرع في الدنيا والآخرة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الأخلاق", source: "رواه مسلم", author_name: "صحيح مسلم" },
  { text: "الصبر نصف الإيمان؛ فمن صبر على البلاء نال الأجر، ومن جزع فقد خيراً كثيراً، وهذا من أصول الاعتقاد التي يُبنى عليها إيمان المسلم وعمله في كل موقف. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "العقيدة", source: "رواه أبو نعيم في الحلية", author_name: "حلية الأولياء" },
  { text: "من سلك طريقاً يلتمس فيه علماً سهّل الله له به طريقاً إلى الجنة؛ فطلب العلم عبادة وطريق نجاة لا مجرد جمع معلومات، وهذا من آداب طلب العلم وأصوله. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "طلب العلم", source: "رواه مسلم", author_name: "صحيح مسلم" },
  { text: "خيركم من تعلّم القرآن وعلّمه؛ فالتعامل مع كتاب الله يستوجب تدبره وحفظه ونشره بين الناس بما ينفعهم في الدنيا والآخرة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "القرآن", source: "رواه البخاري", author_name: "صحيح البخاري" },
  { text: "من أحب لقاء الله أحب الله لقاءه؛ فمحبة الله تظهر في محبة لقائه يوم القيامة، وهذا من أصول الاعتقاد التي يُبنى عليها إيمان المسلم وعمله. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "العقيدة", source: "رواه البخاري (6509)", author_name: "صحيح البخاري" },
  { text: "الدعاء هو العبادة؛ فمن أكثر من الدعاء تقرّب إلى الله ونال الإجابة، وهذا من آداب الإسلام التي تُجمّل المسلم وتُقربه من ربه في السر والعلن. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الآداب", source: "رواه الترمذي (3372) — حسنه الألباني", author_name: "سنن الترمذي" },
  { text: "من صلى عليّ صلاة صلى الله عليه بها عشراً؛ فالصلاة على النبي ﷺ من أعظم القربات، وهذا من هدي النبي ﷺ الذي يجب على المسلم معرفته والعمل به. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الحديث", source: "رواه مسلم", author_name: "صحيح مسلم" },
  { text: "لا يؤمن أحدكم حتى يحب لأخيه ما يحب لنفسه؛ فالإيثار من تمام الإيمان، وهذا من مكارم الأخلاق التي أمر بها الشرع في الدنيا والآخرة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الأخلاق", source: "متفق عليه", author_name: "صحيح البخاري" },
  { text: "المؤمن للمؤمن كالبنيان يشد بعضه بعضاً؛ فالتعاون بين المسلمين من أصول الإسلام، وهذا من آداب الإسلام التي تُجمّل المسلم وتُقربه من ربه. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الآداب", source: "متفق عليه", author_name: "صحيح البخاري" },
  { text: "من كان في حاجة أخيه كان الله في حاجته؛ فنصرة المسلم واجبة، وهذا من آداب الإسلام التي تُجمّل المسلم وتُقربه من ربه في معاملة إخوانه. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الآداب", source: "رواه مسلم", author_name: "صحيح مسلم" }
];
